cells={(r,c) for r,row in enumerate([[0,8,8,0,8,8,0],[8,8,8,8,8,8,0],[0,8,8,0,8,0,0],[0,0,8,8,8,0,0]]) for c,x in enumerate(row) if x==8}
# all tile placements: 2x2 squares and L trominoes, exact covers
sq=[]; ls=[]
for r in range(4):
 for c in range(6):
  block={(r,c),(r+1,c),(r,c+1),(r+1,c+1)}
  if block<=cells: sq.append(block)
  for miss in [(r,c),(r,c+1),(r+1,c),(r+1,c+1)]:
   tile={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}-{miss}
   if tile<=cells: ls.append((tile,miss))
print('squares',sq)
sol=[]
def rec(rem, chosen, n_sq):
 if not rem:
  if n_sq==1 and len(chosen)==5: sol.append(chosen)
  return
 p=min(rem)
 for t in sq:
  if p in t and t<=rem and n_sq<1: rec(rem-t,chosen+[('S',t)],n_sq+1)
 for t,m in ls:
  if p in t and t<=rem: rec(rem-t,chosen+[('L',t,m)],n_sq)
rec(cells,[],0)
print(len(sol))
for ss in sol[:20]: print(ss)
